def solve(inputs: dict) -> float:
    """Compute the sum of entries of a square matrix raised to a power modulo m."""
    A = (inputs.get('matrix') or inputs.get('M') or inputs.get('A'))
    exponent = inputs.get('power', inputs.get('exponent', inputs.get('n', inputs.get('p'))))
    modulus = inputs.get('modulus', inputs.get('mod', inputs.get('m')))
    if A is None:
        for v in inputs.values():
            if isinstance(v, (list, tuple)) and v and isinstance(v[0], (list, tuple)):
                A = v
                break
    if exponent is None or modulus is None:
        nums = [v for v in inputs.values() if isinstance(v, int)]
        if exponent is None and nums:
            exponent = nums[0]
        if modulus is None and len(nums) > 1:
            modulus = nums[1]
    exponent, modulus = int(exponent), int(modulus)
    A = [[int(x) % modulus for x in row] for row in A]
    size = len(A)

    def multiply(X, Y):
        return [[sum(X[i][k] * Y[k][j] for k in range(size)) % modulus
                 for j in range(size)] for i in range(size)]

    result = [[int(i == j) for j in range(size)] for i in range(size)]
    while exponent:
        if exponent & 1:
            result = multiply(result, A)
        A = multiply(A, A)
        exponent >>= 1
    return sum(map(sum, result))

