def solve(inputs: dict) -> float:
    """Return base**exponent modulo modulus."""
    base = inputs.get('base', inputs.get('a', inputs.get('number', inputs.get('value'))))
    exponent = inputs.get('exponent', inputs.get('power', inputs.get('exp', inputs.get('n'))))
    modulus = inputs.get('modulus', inputs.get('mod', inputs.get('m')))
    if base is None or exponent is None or modulus is None:
        vals = list(inputs.values())
        if len(vals) == 3:
            base, exponent, modulus = vals
        else:
            raise ValueError('Expected base, exponent, and modulus')
    return pow(int(base), int(exponent), int(modulus))

